export default class KimaiEscape extends KimaiPlugin {

    getId() {
        return 'escape';
    }

    /**

     */
    escapeForHtml(title) {
        if (title === undefined || title === null) {
            return '';
        }

        const charToReplace = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
        };

        return title.replace(/[&<>"]/g, function(tag) {
            return charToReplace[tag] || tag;
        });
    }

    /**
