	const writers = 32
	const reads = 64
	const writesPerGoroutine = 100

	var wg sync.WaitGroup
	wg.Add(writers + reads + 1)

	for i := 0; i < writers; i++ {
		go func(id int) {
			defer wg.Done()
			key := v2.SimpleRequestDefinitionView{
				Host: "test.com",
				Path: "/" + strconv.Itoa(id),
			}
			for j := 0; j < writesPerGoroutine; j++ {
