  id: build
  uses: docker/build-push-action@10e90e3645eae34f1e60eeb005ba3a3d33f178e8 # v6
  with:
    context: .
    file: Containerfile.lite
    platforms: ${{ matrix.platform }}

    push: ${{ github.event_name != 'pull_request' }}
    load: ${{ github.event_name == 'pull_request' }}

    tags: ${{ steps.meta.outputs.tags }}
    labels: ${{ steps.meta.outputs.labels }}
    cache-from: type=gha,scope=containerfile-lite-${{ matrix.suffix }}
    cache-to: type=gha,mode=${{ matrix.cache_mode }},scope=containerfile-lite-${{ matrix.suffix }}
    provenance: false

- name: Export digest

        labels: ${{ steps.meta.outputs.labels }}
        cache-from: type=gha,scope=containerfile-lite-${{ matrix.suffix }}
        cache-to: type=gha,mode=${{ matrix.cache_mode }},scope=containerfile-lite-${{ matrix.suffix }}
        provenance: false

    - name: Export digest
      if: (matrix.run_on_pr || github.event_name != 'pull_request') && github.event_name != 'pull_request' && (!matrix.tag_only || startsWith(github.ref, 'refs/tags/'))
      run: |
        mkdir -p /tmp/digests
        digest="${{ steps.build.outputs.digest }}"
        touch "/tmp/digests/${digest#sha256:}"
        echo "Digest for ${{ matrix.suffix }}: $digest"

    - name: Upload digest
      if: (matrix.run_on_pr || github.event_name != 'pull_request') && github.event_name != 'pull_request' && (!matrix.tag_only || startsWith(github.ref, 'refs/tags/'))
      uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4
      with:
        name: digest-${{ matrix.suffix }}
        path: /tmp/digests/*
        if-no-files-found: error
        retention-days: 1

